package com.agacostays.payroll.controller; import com.agacostays.payroll.dto.request.SalarySlipRequest;import com.agacostays.payroll.dto.response.*;import com.agacostays.payroll.service.SalarySlipService;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController public class SalarySlipController{final SalarySlipService s;public SalarySlipController(SalarySlipService s){this.s=s;}@PostMapping("/api/manager/payroll/{payrollId}/salary-slip") public ResponseEntity<ApiResponse<SalarySlipResponse>> generate(@PathVariable Long payrollId){return ResponseEntity.ok(ApiResponse.ok("Salary slip generated",s.generate(payrollId)));}@GetMapping({"/api/manager/payroll/{payrollId}/salary-slip","/api/payroll/{payrollId}/salary-slip"}) public ResponseEntity<byte[]> download(@PathVariable Long payrollId){return ResponseEntity.ok().contentType(MediaType.TEXT_PLAIN).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=salary-slip-"+payrollId+".txt").body(s.download(payrollId));}@PostMapping("/api/manager/payroll/{payrollId}/send-salary-slip-email") public ResponseEntity<ApiResponse<Void>> send(@PathVariable Long payrollId,@RequestBody(required=false) SalarySlipRequest r){s.sendEmail(payrollId,r==null?null:r.recipientEmail());return ResponseEntity.ok(ApiResponse.ok("Salary slip email queued",null));}}
